export type BetaManagedAgentsMcpOauthRefreshParams = {
  readonly "refresh_token": string
  readonly "token_endpoint": string
  readonly "client_id": string
  readonly "scope"?: string
  readonly "resource"?: string
  readonly "token_endpoint_auth": { readonly "type": "none" } | {
    readonly "type": "client_secret_basic"
    readonly "client_secret": string
  } | { readonly "type": "client_secret_post"; readonly "client_secret": string }
}
export const BetaManagedAgentsMcpOauthRefreshParams = Schema.Struct({
  "refresh_token": Schema.String.annotate({ "description": "OAuth refresh token." }).check(
    Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })
  ).check(Schema.isMaxLength(4096).annotate({ "expected": "a value with a length of at most 4096" })),
  "token_endpoint": Schema.String.annotate({ "description": "Token endpoint URL used to refresh the access token." })
    .check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })).check(
      Schema.isMaxLength(2047).annotate({ "expected": "a value with a length of at most 2047" })
    ),
  "client_id": Schema.String.annotate({ "description": "OAuth client ID." }).check(
    Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })
  ).check(Schema.isMaxLength(1024).annotate({ "expected": "a value with a length of at most 1024" })),
  "scope": Schema.optionalKey(
    Schema.String.annotate({ "description": "OAuth scope for the refresh request." }).check(
      Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })
    ).check(Schema.isMaxLength(8192).annotate({ "expected": "a value with a length of at most 8192" }))
  ),
  "resource": Schema.optionalKey(
    Schema.String.annotate({ "description": "OAuth resource indicator." }).check(
      Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })
    ).check(Schema.isMaxLength(2047).annotate({ "expected": "a value with a length of at most 2047" }))
  ),
  "token_endpoint_auth": Schema.Union([
    Schema.Struct({ "type": Schema.Literal("none") }).annotate({
      "description": "Token endpoint requires no client authentication."
    }),
    Schema.Struct({
      "type": Schema.Literal("client_secret_basic"),
      "client_secret": Schema.String.annotate({ "description": "OAuth client secret." }).check(
        Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })
      ).check(Schema.isMaxLength(512).annotate({ "expected": "a value with a length of at most 512" }))
    }).annotate({ "description": "Token endpoint uses HTTP Basic authentication with client credentials." }),
    Schema.Struct({
      "type": Schema.Literal("client_secret_post"),
      "client_secret": Schema.String.annotate({ "description": "OAuth client secret." }).check(
        Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })
      ).check(Schema.isMaxLength(512).annotate({ "expected": "a value with a length of at most 512" }))
    }).annotate({ "description": "Token endpoint uses POST body authentication with client credentials." })
  ], { mode: "oneOf" })
}).annotate({
  "description": "OAuth refresh token parameters for creating a credential with refresh support.",
  "identifier": "BetaManagedAgentsMcpOauthRefreshParams"
})
