export type CompletionRequest = {
  readonly "model": Model
  readonly "prompt": string
  readonly "max_tokens_to_sample": number
  readonly "stop_sequences"?: ReadonlyArray<string>
  readonly "temperature"?: number
  readonly "top_p"?: number
  readonly "top_k"?: number
  readonly "metadata"?: Metadata
  readonly "stream"?: boolean
}
export const CompletionRequest = Schema.Struct({
  "model": Model,
  "prompt": Schema.String.annotate({
    "title": "Prompt",
    "description":
      "The prompt that you want Claude to complete.\n\nFor proper response generation you will need to format your prompt using alternating `\\n\\nHuman:` and `\\n\\nAssistant:` conversational turns. For example:\n\n```\n\"\\n\\nHuman: {userQuestion}\\n\\nAssistant:\"\n```\n\nSee [prompt validation](https://platform.claude.com/docs/en/build-with-claude/working-with-messages) and our guide to [prompt design](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview) for more details."
  }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })),
  "max_tokens_to_sample": Schema.Number.annotate({
    "title": "Max Tokens To Sample",
    "description":
      "The maximum number of tokens to generate before stopping.\n\nNote that our models may stop _before_ reaching this maximum. This parameter only specifies the absolute maximum number of tokens to generate."
  }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(
    Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" })
  ),
  "stop_sequences": Schema.optionalKey(
    Schema.Array(Schema.String).annotate({
      "title": "Stop Sequences",
      "description":
        "Sequences that will cause the model to stop generating.\n\nOur models stop on `\"\\n\\nHuman:\"`, and may include additional built-in stop sequences in the future. By providing the stop_sequences parameter, you may include additional strings that will cause the model to stop generating."
    })
  ),
  "temperature": Schema.optionalKey(
    Schema.Number.annotate({
      "title": "Temperature",
      "description":
        "Amount of randomness injected into the response.\n\nDefaults to `1.0`. Ranges from `0.0` to `1.0`. Use `temperature` closer to `0.0` for analytical / multiple choice, and closer to `1.0` for creative and generative tasks.\n\nNote that even with `temperature` of `0.0`, the results will not be fully deterministic."
    }).check(Schema.isFinite().annotate({ "expected": "a finite number" })).check(
      Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })
    ).check(Schema.isLessThanOrEqualTo(1).annotate({ "expected": "a value less than or equal to 1" }))
  ),
  "top_p": Schema.optionalKey(
    Schema.Number.annotate({
      "title": "Top P",
      "description":
        "Use nucleus sampling.\n\nIn nucleus sampling, we compute the cumulative distribution over all the options for each subsequent token in decreasing probability order and cut it off once it reaches a particular probability specified by `top_p`.\n\nRecommended for advanced use cases only."
    }).check(Schema.isFinite().annotate({ "expected": "a finite number" })).check(
      Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })
    ).check(Schema.isLessThanOrEqualTo(1).annotate({ "expected": "a value less than or equal to 1" }))
  ),
  "top_k": Schema.optionalKey(
    Schema.Number.annotate({
      "title": "Top K",
      "description":
        "Only sample from the top K options for each subsequent token.\n\nUsed to remove \"long tail\" low probability responses. [Learn more technical details here](https://towardsdatascience.com/how-to-sample-from-language-models-682bceb97277).\n\nRecommended for advanced use cases only."
    }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(
      Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })
    )
  ),
  "metadata": Schema.optionalKey(
    Schema.suspend((): Schema.Codec<Metadata> => Metadata).annotate({
      "description": "An object describing metadata about the request."
    })
  ),
  "stream": Schema.optionalKey(
    Schema.Boolean.annotate({
      "title": "Stream",
      "description":
        "Whether to incrementally stream the response using server-sent events.\n\nSee [streaming](https://platform.claude.com/docs/en/build-with-claude/streaming) for details."
    })
  )
}).annotate({ "title": "CompletionRequest", "identifier": "CompletionRequest" })
