export type BetaManagedAgentsUpdateMemoryParams = {
  readonly "content"?: string
  readonly "path"?: string
  readonly "precondition"?: BetaManagedAgentsPrecondition
}
export const BetaManagedAgentsUpdateMemoryParams = Schema.Struct({
  "content": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "New UTF-8 text content for the memory. Maximum 100 kB (102,400 bytes). Omit to leave the content unchanged (e.g., for a rename-only update)."
    })
  ),
  "path": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "New path for the memory (a rename). Must start with `/`, contain at least one non-empty segment, and be at most 1,024 bytes. Must not contain empty segments, `.` or `..` segments, control or format characters, and must be NFC-normalized. Paths are case-sensitive. The memory's `id` is preserved across renames. Omit to leave the path unchanged."
    }).check(Schema.isMinLength(2).annotate({ "expected": "a value with a length of at least 2" })).check(
      Schema.isMaxLength(1024).annotate({ "expected": "a value with a length of at most 1024" })
    )
  ),
  "precondition": Schema.optionalKey(
    Schema.suspend((): Schema.Codec<BetaManagedAgentsPrecondition> => BetaManagedAgentsPrecondition).annotate({
      "description":
        "Optional optimistic-concurrency precondition. When supplied, the update applies only if the memory's current state matches; on mismatch the request returns `memory_precondition_failed_error` (HTTP 409). When omitted, the update is unconditional."
    })
  )
}).annotate({
  "description":
    "Request parameters for [Update a memory](/en/api/beta/memory_stores/memories/update). At least one of `content` or `path` must be provided. Renaming onto a path occupied by a different memory returns `memory_path_conflict_error` (HTTP 409). Rename never overwrites; delete or rename the blocking memory first. An update where every supplied field already matches the stored value is a no-op: it returns 200 with the existing memory and writes no new version.",
  "identifier": "BetaManagedAgentsUpdateMemoryParams"
})
export type BetaManagedAgentsMemoryVersion = {
  readonly "type": "memory_version"
  readonly "id": string
  readonly "memory_store_id": string
  readonly "memory_id": string
  readonly "path"?: string
  readonly "operation": BetaManagedAgentsMemoryVersionOperation
  readonly "content"?: string
  readonly "content_size_bytes"?: number
  readonly "content_sha256"?: string
  readonly "created_by"?: BetaManagedAgentsActor
  readonly "created_at": BetaTimestamp
  readonly "redacted_at"?: BetaTimestamp
  readonly "redacted_by"?: BetaManagedAgentsActor
}
export const BetaManagedAgentsMemoryVersion = Schema.Struct({
  "type": Schema.Literal("memory_version"),
  "id": Schema.String.annotate({ "description": "Unique identifier for this version (a `memver_...` value)." }),
  "memory_store_id": Schema.String.annotate({
    "description": "ID of the memory store this version belongs to (a `memstore_...` value)."
  }),
  "memory_id": Schema.String.annotate({
    "description":
      "ID of the memory this version snapshots (a `mem_...` value). Remains valid after the memory is deleted; pass it as `memory_id` to [List memory versions](/en/api/beta/memory_stores/memory_versions/list) to retrieve the full lineage including the `deleted` row."
  }),
  "path": Schema.optionalKey(
    Schema.String.annotate({
      "description": "The memory's path at the time of this write. `null` if and only if `redacted_at` is set."
    })
  ),
  "operation": Schema.suspend((): Schema.Codec<BetaManagedAgentsMemoryVersionOperation> =>
    BetaManagedAgentsMemoryVersionOperation
  ).annotate({ "description": "The kind of mutation this version records: `created`, `modified`, or `deleted`." }),
  "content": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "The memory's UTF-8 text content as of this version. `null` when `view=basic`, when `operation` is `deleted`, or when `redacted_at` is set."
    })
  ),
  "content_size_bytes": Schema.optionalKey(
    Schema.Number.annotate({
      "description":
        "Size of `content` in bytes as of this version. `null` when `redacted_at` is set or `operation` is `deleted`. Populated regardless of `view` otherwise.",
      "format": "int32"
    }).check(Schema.isInt().annotate({ "expected": "an integer" }))
  ),
  "content_sha256": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "Lowercase hex SHA-256 digest of `content` as of this version (64 characters). `null` when `redacted_at` is set or `operation` is `deleted`. Populated regardless of `view` otherwise."
    })
  ),
  "created_by": Schema.optionalKey(
    Schema.suspend((): Schema.Codec<BetaManagedAgentsActor> => BetaManagedAgentsActor).annotate({
      "description":
        "Who performed this write: a `session_actor`, `api_actor`, or `user_actor`. Captured at write time and preserved through redaction."
    })
  ),
  "created_at": Schema.suspend((): Schema.Codec<BetaTimestamp> => BetaTimestamp).annotate({
    "description": "When this version was written, in RFC 3339 format."
  }),
  "redacted_at": Schema.optionalKey(
    Schema.suspend((): Schema.Codec<BetaTimestamp> => BetaTimestamp).annotate({
      "description":
        "When this version was redacted, in RFC 3339 format, or `null` if it has not been redacted. When set, `content`, `path`, `content_size_bytes`, and `content_sha256` are all `null`. See [Redact a memory version](/en/api/beta/memory_stores/memory_versions/redact)."
    })
  ),
  "redacted_by": Schema.optionalKey(
    Schema.suspend((): Schema.Codec<BetaManagedAgentsActor> => BetaManagedAgentsActor).annotate({
      "description":
        "Who redacted this version, or `null` if it has not been redacted. In practice always an `api_actor` or `user_actor` (agents do not have a redact capability)."
    })
  )
}).annotate({
  "description":
    "A `memory_version` object: one immutable, attributed row in a memory's append-only history. Every non-no-op mutation to a memory produces a new version. Versions belong to the store (not the individual memory) and persist after the memory is deleted. Retrieving a redacted version returns 200 with `content`, `path`, `content_size_bytes`, and `content_sha256` set to `null`; branch on `redacted_at`, not HTTP status.",
  "identifier": "BetaManagedAgentsMemoryVersion"
})
