export const MessageBatchIndividualRequestParams = Schema.Struct({
  "custom_id": Schema.String.annotate({
    "title": "Custom Id",
    "description":
      "Developer-provided ID created for each request in a Message Batch. Useful for matching results to requests, as results may be given out of request order.\n\nMust be unique for each request within the Message Batch."
  }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })).check(
    Schema.isMaxLength(64).annotate({ "expected": "a value with a length of at most 64" })
  ).check(
    Schema.isPattern(new RegExp("^[a-zA-Z0-9_-]{1,64}$")).annotate({
      "expected": "a string matching the RegExp ^[a-zA-Z0-9_-]{1,64}$"
    })
  ),
  "params": Schema.suspend((): Schema.Codec<CreateMessageParams> => CreateMessageParams).annotate({
    "description":
      "Messages API creation parameters for the individual request.\n\nSee the [Messages API reference](https://platform.claude.com/docs/en/api/messages) for full documentation on available parameters."
  })
}).annotate({ "title": "MessageBatchIndividualRequestParams", "identifier": "MessageBatchIndividualRequestParams" })
